window.kbPageData["views/entry/k-091087790f3288aa"] = {"key":"entry/k-091087790f3288aa","state":{"route":"entry/k-091087790f3288aa"},"node":{"id":"k-091087790f3288aa","mode":"k","title":"螳臂当车与自不量力","type":"概念与词义","domain":"汉语","reading":"","intro":"","priority":100,"aliases":["螳臂当车与自不量力的近义关系","螳臂当车与自不量力的词义"],"qs":["江苏 2024 A类 行测#74","江苏 2024 C类 行测#74"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":1,"directorySummary":"螳臂当车比喻高估自己的力量，去做力所不能及的事。自不量力指不能正确估量自己的能力，多指去做超出能力范围的事。","review":{"definition":"螳臂当车比喻高估自己的力量，去做力所不能及的事。自不量力指不能正确估量自己的能力，多指去做超出能力范围的事。","explanation":"螳臂当车常用来形容以弱小力量阻挡强大事物，自不量力的适用范围更广。两词都能形容高估自身能力而去做办不到的事，因此A项后半组与前半组同为近义关系。D项的自以为是侧重认定自己的看法或做法正确。","references":[],"evidence":"“螳臂当车”比喻不正确估计自己的力量，去做办不到的事情","disposition":"独立词条","basis":"据原题和解析编释。","title":"螳臂当车与自不量力","related":[],"examFocus":{"江苏 2024 A类 行测#74":"把成语分别代入两空，比较每对成语的含义和使用情境，判断前后两组的词义关系是否一致。"}},"readings":[{"origin":"k-091087790f3288aa","title":"螳臂当车与自不量力","qs":["江苏 2024 C类 行测#74"],"definition":"螳臂当车比喻高估自己的力量，去做力所不能及的事。自不量力指不能正确估量自己的能力，多指去做超出能力范围的事。","explanation":"螳臂当车常用来形容以弱小力量阻挡强大事物，自不量力的适用范围更广。两词都能形容高估自身能力而去做办不到的事，因此A项后半组与前半组同为近义关系。D项的自以为是侧重认定自己的看法或做法正确。","evidence":"“螳臂当车”比喻不正确估计自己的力量，去做办不到的事情","doubt":"","references":[]},{"origin":"k-1b48d3f941d81a5c","title":"螳臂当车与自不量力","qs":["江苏 2024 A类 行测#74"],"definition":"螳臂当车比喻力量不足却试图阻挡强大的对手或事物。自不量力指不能正确估计自己的力量，多指高估自己，去做力所不能及的事。","explanation":"“螳臂当车”突出用弱小的力量去抵挡强大的事物，是自不量力的一种表现。A 项后一组据此构成近义关系，与前一组“杞人忧天”和“庸人自扰”的关系一致。D 项的“自以为是”侧重认定自己的看法或做法正确，和估计自身力量是两回事。","evidence":"“螳臂当车”比喻不正确估计自己的力量，去做办不到的事情","doubt":"","references":[]}]},"questions":{"江苏 2024 A类 行测#74":{"paper":"江苏 2024 A类 行测","n":74,"mod":"判断推理","src":["f8fec75f67d6d1ba5759.pdf",12],"asrc":["0126a1c8aceee632ea2b.pdf",22],"card":"04b74982480506f0bcd4fbf2","links":[{"id":"k-091087790f3288aa","role":"直接考查","why":"两个成语都含有高估自身力量、试图做力所不能及之事的意思，这是判断后一词对近义的依据。"}]},"江苏 2024 C类 行测#74":{"paper":"江苏 2024 C类 行测","n":74,"mod":"判断推理","src":["3f1ec77ae8a18519b57e.pdf",12],"asrc":["02d6b49839583bdaf297.pdf",21],"card":"f434f8a0c3d63ea57d31fb38","links":[{"id":"k-091087790f3288aa","role":"解题依据","why":"两个成语都可指没有正确估计自己的力量，去做力所不能及的事。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-091087790f3288aa":[["江苏 2024 A类 行测#74","江苏 2024 C类 行测#74"]]}};
